import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ============================================================================
  // 1. LOAD TEXTURE
  // ============================================================================
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);

  // ============================================================================
  // 2. CREATE TEXT
  // ============================================================================
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textItem = textItems.find(item => item.role === 'headline') || textItems[0];
  const textContent = textItem?.text || 'Features 3';

  const textMesh = ctx.fontAtlas.createText(textContent, {
    fontSize: 39,
    color: '#16161d',
    align: 'center',
  });

  // ============================================================================
  // 3. CREATE SPRITE PLANE
  // ============================================================================
  // Atlas region: 512x320 = 1.6:1 aspect ratio
  const atlasAspect = 512 / 320;
  const planeWidth = 1.6;
  const planeHeight = 1.0;

  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  // UV offset for atlas region (0, 0, 512, 320 within a larger atlas)
  // Assuming single-atlas region at top-left (no offset needed if single texture)
  const uvAttr = geometry.getAttribute('uv');
  // Texture coordinates: region starts at (0, 0) and spans (512, 320)
  // If this is the entire texture, UVs remain [0,1] x [0,1]
  // If atlas is larger, compute: offsetX = 0/atlasWidth, offsetY = 0/atlasHeight, scaleX = 512/atlasWidth, scaleY = 320/atlasHeight
  // For now, assume the provided texture is pre-cropped to region

  const material = new MeshBasicNodeMaterial({
    transparent: true,
  });

  // Set up material with texture node
  texturePromise.then((texture) => {
    texture.colorSpace = THREE.SRGBColorSpace;
    const uvNode = uv();
    material.colorNode = uvNode.mul(vec2(texture)).sample(texture);
    material.map = texture;
    material.needsUpdate = true;
  }).catch((err) => {
    console.error('Texture load failed:', err);
    material.color.setHex(0x16161d);
  });

  const plane = new THREE.Mesh(geometry, material);
  plane.position.z = 0.01; // Slight z-offset for layering

  // ============================================================================
  // 4. ASSEMBLE GROUP
  // ============================================================================
  const group = new THREE.Group();
  group.add(plane);
  group.add(textMesh);

  // Position text overlay (centered on plane)
  textMesh.position.z = 0.02;
  textMesh.position.y = -0.15;

  // ============================================================================
  // 5. CLEANUP
  // ============================================================================
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texturePromise.then((tex) => tex.dispose()).catch(() => {});
  };

  group.userData.handlers = {};

  return group;
}
